SELECT DISTINCT c.customer_email
FROM Customers AS c
JOIN Accounts AS a ON c.customer_last_name = a.account_name;

SELECT DISTINCT c.customer_email
FROM Customers c
JOIN Accounts a ON c.customer_last_name = a.account_name;

SELECT DISTINCT c.customer_first_name, c.customer_last_name, ft.transaction_comment
FROM Financial_Transactions ft
JOIN Customers c ON ft.transaction_comment LIKE '%' || c.customer_first_name || ' ' || c.customer_last_name || '%';
